import{_ as e,o,c as t,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"LocalSend 로컬 전송 설정","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/localsend.md","filePath":"ko-KR/user-guide/settings/localsend.md","lastUpdated":1785993908000}'),r={name:"ko-KR/user-guide/settings/localsend.md"};function n(s,a,i,d,c,g){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="localsend-로컬-전송-설정" tabindex="-1">LocalSend 로컬 전송 설정 <a class="header-anchor" href="#localsend-로컬-전송-설정" aria-label="Permalink to &quot;LocalSend 로컬 전송 설정&quot;">​</a></h1><p>Lertaro에는 공식 <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> 프로토콜과 호환되는 로컬 네트워크 전송 기능이 내장되어 있어, 동일한 LAN 환경의 모바일 및 PC 기기 간에 파일, 폴더 및 텍스트를 전송할 수 있습니다. 설정 경로는 <strong>설정 → LocalSend</strong>입니다.</p><h2 id="기본-설정" tabindex="-1">기본 설정 <a class="header-anchor" href="#기본-설정" aria-label="Permalink to &quot;기본 설정&quot;">​</a></h2><ul><li><strong>LocalSend 로컬 전송 활성화</strong> —— LocalSend 전송 서비스의 켜기/끄기를 설정합니다. 활성화 시 트레이 메뉴에 &quot;LocalSend로 전송...&quot; 항목이 표시되며 전역 단축키에 응답합니다.</li><li><strong>기기 이름</strong> —— LAN의 다른 LocalSend 클라이언트에 표시되는 이름입니다. 기본적으로 컴퓨터 이름으로 자동 생성됩니다.</li><li><strong>서비스 포트</strong> —— 전송 요청을 수신하는 HTTP/HTTPS 포트입니다 (기본값 <code>53317</code>).</li></ul><h2 id="보안-및-암호화" tabindex="-1">보안 및 암호화 <a class="header-anchor" href="#보안-및-암호화" aria-label="Permalink to &quot;보안 및 암호화&quot;">​</a></h2><ul><li><strong>암호화 전송 (HTTPS)</strong> —— 데이터 전송 시 HTTPS 암호화 연결을 사용합니다 (상대 기기의 암호화 지원 필요).</li><li><strong>수신 PIN 코드</strong> —— 전송 수신 시 인증할 PIN 코드를 설정합니다 (비워두면 비활성화).</li></ul><h2 id="수신-및-저장" tabindex="-1">수신 및 저장 <a class="header-anchor" href="#수신-및-저장" aria-label="Permalink to &quot;수신 및 저장&quot;">​</a></h2><ul><li><strong>자동 저장 (Quick Save)</strong> —— 수신된 파일을 매번 수동으로 확인하지 않고 자동으로 저장합니다.</li><li><strong>저장 폴더</strong> —— 수신된 파일이 저장될 기본 경로입니다.</li></ul><h2 id="불러오기-및-전송-모드" tabindex="-1">불러오기 및 전송 모드 <a class="header-anchor" href="#불러오기-및-전송-모드" aria-label="Permalink to &quot;불러오기 및 전송 모드&quot;">​</a></h2><ul><li><strong>단축키 불러오기</strong> —— 기본값 <strong><code>Ctrl+S</code></strong> (<a href="./hotkeys-page.html">단축키 설정</a>에서 변경 가능) 또는 트레이 메뉴를 통해 전송 창을 엽니다.</li><li><strong>모드 전환</strong> —— 전송 창에서 [ 파일 / 폴더 전송 ] 및 [ 텍스트 전송 ] 모드를 전환할 수 있습니다.</li></ul>',10)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
